args.body:
// 泵站启停控制逻辑
if (PUMP_CMD == 1) {
    // 启动命令
    PUMP_RUN_STATUS = 1;
    log("泵站启动命令已执行");
} else if (PUMP_CMD == 0) {
    // 停止命令
    PUMP_RUN_STATUS = 0;
    log("泵站停止命令已执行");
}

// 泵站运行状态监测
if (PUMP_RUN_STATUS == 1) {
    // 泵运行中，检查各项参数
    if (PUMP_TEMP > 85) {
        trigger_alarm("alarm_pump_temp_high");
    }
    if (PUMP_PRESSURE > 8) {
        trigger_alarm("alarm_pump_pressure_high");
    }
    if (PUMP_FLOW < 10) {
        trigger_alarm("alarm_pump_flow_low");
    }
    // 记录运行时间
    PUMP_RUNTIME_HOURS += 5/3600;
}

