// 故障处理逻辑
if (PUMP_FAULT == 1) {
    // 故障发生，立即停泵
    PUMP_CMD = 0;
    PUMP_RUN_STATUS = 0;
    log("检测到泵故障，已自动停泵");

    // 触发故障报警
    trigger_alarm("alarm_pump_fault");
}
